#include "symm.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

/**
 * Array initialization, translated from the original C version.
 *
 * Original C signature:
 *   void init_array(int m, int n,
 *                   DATA_TYPE *alpha,
 *                   DATA_TYPE *beta,
 *                   DATA_TYPE C[M][N],
 *                   DATA_TYPE A[M][M],
 *                   DATA_TYPE B[M][N]);
 *
 * Mapping:
 *   - C[i][j] (MxN) -> Buffer C(j, i) with shape (n, m)
 *   - B[i][j] (MxN) -> Buffer B(j, i) with shape (n, m)
 *   - A[i][j] (MxM) -> Buffer A(j, i) with shape (m, m)
 */
static
void init_array(int m, int n,
                num_t *alpha,
                num_t *beta,
                Halide::Buffer<num_t, 2> C,
                Halide::Buffer<num_t, 2> A,
                Halide::Buffer<num_t, 2> B) {
    *alpha = (num_t)1.5;
    *beta  = (num_t)1.2;

    Var i("i"), j("j");

    // Initialize C and B:
    //
    // C[i][j] = (DATA_TYPE)((i + j) % 100) / m;
    // B[i][j] = (DATA_TYPE)((n + i - j) % 100) / m;
    //
    // With our Buffer layout C(j, i), B(j, i):
    Func init_C("init_C"), init_B("init_B");

    init_C(j, i) = cast<num_t>(((i + j) % 100)) / cast<int>(m);
    init_B(j, i) = cast<num_t>(((n + i - j) % 100)) / cast<int>(m);

    // Initialize A:
    //
    // for (i = 0; i < m; i++) {
    //   for (j = 0; j <= i; j++)
    //       A[i][j] = (DATA_TYPE)((i + j) % 100) / m;
    //   for (j = i+1; j < m; j++)
    //       A[i][j] = -999;
    // }
    //
    // We store A[i][j] at A(j, i), and fill the "unused" upper part with -999.
    Func init_A("init_A");
    Expr lower_tri = cast<num_t>(((i + j) % 100)) / cast<int>(m);
    Expr unused    = cast<num_t>(-999);
    init_A(j, i)   = select(j <= i, lower_tri, unused);

    // Simple, cache‑friendly schedule for initialization:
    //  - Parallelize over rows (i)
    //  - Vectorize over contiguous x-dimension (j)
    Target init_target = get_host_target();
    const int vec_init = std::max(1, init_target.natural_vector_size(type_of<num_t>()));

    init_C.parallel(i).vectorize(j, vec_init);
    init_B.parallel(i).vectorize(j, vec_init);
    init_A.parallel(i).vectorize(j, vec_init);

    // Realize into the provided buffers
    init_C.realize(C);
    init_B.realize(B);
    init_A.realize(A);
}

int main(int argc, char *argv[]) {
    // Problem size (from symm.hpp / defines.hpp)
    int m = M;
    int n = N;

    // Scalars
    num_t alpha;
    num_t beta;

    // Buffers:
    //   C, B : MxN  -> (n, m) in Halide
    //   A    : MxM  -> (m, m) in Halide
    Halide::Buffer<num_t, 2> C(n, m);
    Halide::Buffer<num_t, 2> B(n, m);
    Halide::Buffer<num_t, 2> A(m, m);

    // ImageParams to pass the buffers into the Halide pipeline
    ImageParam C_param(type_of<num_t>(), 2, "C_param");
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam B_param(type_of<num_t>(), 2, "B_param");

    // Initialize data
    init_array(m, n, &alpha, &beta, C, A, B);

    // Bind buffers to ImageParams
    C_param.set(C);
    A_param.set(A);
    B_param.set(B);

    // Vars and reduction domain
    Var i("i"), j("j");
    // A is MxM stored as A(j, i); extent of dim(0) is m
    RDom k(0, A.dim(0).extent(), "k");

    // --------------------------------------------------------------------
    // Optimized Halide pipeline for SYMM:
    //
    // Math semantics (BLAS symm):
    //   C := alpha * A * B + beta * C
    //
    // with A symmetric, stored in its lower triangular part.
    //
    // Mapping (original -> Halide):
    //   A[i][l]  -> A_param(l, i)
    //   A[l][i]  -> A_param(i, l)
    //   B[i][j]  -> B_param(j, i)
    //   C[i][j]  -> C_param(j, i)
    //
    // We construct a symmetric view of A:
    //   A_sym(i, k) =
    //      (k <= i) ? A_param(k, i)  : A_param(i, k)
    //
    // And compute:
    //   C_out(j, i) = beta * C_param(j, i)
    //   C_out(j, i) += sum_k A_sym(i, k) * (alpha * B_param(j, k))
    //
    // Note the re-association:
    //   alpha * sum_k A_sym(i, k) * B(j, k)
    // = sum_k A_sym(i, k) * (alpha * B(j, k))
    //
    // This lets us pre-scale B by alpha once, instead of multiplying
    // by alpha inside the innermost (i, j, k) loop, which reduces
    // the total number of multiplications.
    // --------------------------------------------------------------------

    // Pre-scale B by alpha: B_scaled(j, k) = alpha * B_param(j, k)
    // This is a pure Func and can be computed once, fully vectorized.
    Var kk("kk");
    Func B_scaled("B_scaled");
    B_scaled(j, kk) = Expr(alpha) * B_param(j, kk);

    // Main computational kernel.
    Func symm("symm");

    // Base: beta * C (in-place update onto C's storage)
    symm(j, i) = Expr(beta) * C_param(j, i);

    // Symmetric access to A
    Expr A_sym = select(k <= i, A_param(k, i), A_param(i, k));

    // Accumulate A_sym * B_scaled
    symm(j, i) += A_sym * B_scaled(j, k);

    // --------------------------------------------------------------------
    // Scheduling
    //
    // Goals:
    //  - Good cache locality for all of A, B, C
    //  - Exploit SIMD (vectorization) along the contiguous j-dimension
    //  - Exploit parallelism across tiles of (i, j)
    //  - Avoid recomputing expensive expressions inside inner loops
    // --------------------------------------------------------------------

    Target target = get_host_target();
    const int vec_width = std::max(1, target.natural_vector_size(type_of<num_t>()));

    // 1) Schedule B_scaled:
    //
    //    B_scaled is read many times inside the k-loop; precomputing it once
    //    saves an extra multiply by alpha for every (i, j, k).
    //
    //    Layout: B_scaled(j, kk) -> dimension 0 (j) is contiguous.
    //
    //    We:
    //      - compute it at root,
    //      - parallelize over the kk (row) dimension,
    //      - vectorize over j.
    B_scaled
        .compute_root()
        .parallel(kk)
        .vectorize(j, vec_width);

    // 2) Schedule symm:
    //
    //    We tile the (j, i) plane into tiles of size TILE_J x TILE_I to improve
    //    data locality, then fuse the tile indices and parallelize across tiles.
    //    Within each tile we vectorize along the contiguous j direction.
    //
    //    For the reduction update, we use the same tiling but reorder loops to:
    //       for tile (fused as tile_index)
    //         for k
    //           for i_inner
    //             for j_inner (vectorized)
    //
    //    This has the typical blocked GEMM structure and gives:
    //      - good reuse of A_sym(i, k) across j_inner within a tile,
    //      - streaming access to B_scaled(j, k) along j,
    //      - streaming writes to C(j, i) along j.
    constexpr int TILE_I = 32;  // tile size in i (rows)
    constexpr int TILE_J = 64;  // tile size in j (cols)

    Var i_outer("i_outer"), i_inner("i_inner");
    Var j_outer("j_outer"), j_inner("j_inner");
    Var tile_index("tile_index");

    // Tile and fuse for the pure definition (beta * C)
    symm
        .tile(j, i, j_outer, i_outer, j_inner, i_inner, TILE_J, TILE_I)
        // Fuse tile indices so we can parallelize across tiles
        .fuse(i_outer, j_outer, tile_index)
        .parallel(tile_index)
        .vectorize(j_inner, vec_width);

    // Apply a compatible schedule to the update (reduction) stage.
    // The tiling and fusion we applied above also affect this stage;
    // here we just reorder and parallelize the existing Vars.
    symm.update()
        // From innermost to outermost: j_inner (SIMD), i_inner, k, tile_index
        .reorder(j_inner, i_inner, k, tile_index)
        .parallel(tile_index)
        .vectorize(j_inner, vec_width);

    // JIT-compile the kernel (this compiles symm, B_scaled, and everything they depend on)
    symm.compile_jit(target);

    // Time the kernel
    auto start = std::chrono::high_resolution_clock::now();

    // Run kernel: write result back into C
    // Note: C is both input (via C_param) and output; the computation
    // reads C_param(j, i) once for each (j, i) before overwriting C(j, i),
    // so the in-place update is well-defined.
    symm.realize(C);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Print results (mainly to prevent dead-code elimination),
    // following the style of the GEMM example.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int ii = 0; ii < m; ii++) {
            for (int jj = 0; jj < n; jj++) {
                // C(ii, jj) in C layout is C(jj, ii) in our Buffer
                std::cerr << C(jj, ii) << '\n';
            }
        }
    }

    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
