    // ----------------------------------
    // Initialize C and B
    // ----------------------------------
    //
    // Original C:
    //   C[i][j] = (DATA_TYPE)((i + j) % 100) / m;
    //   B[i][j] = (DATA_TYPE)((n + i - j) % 100) / m;
    //
    // With our Buffer layout C(j, i), B(j, i):
    Func init_C("init_C"), init_B("init_B");

    init_C(j, i) = cast<num_t>(((i + j) % 100)) / cast<int>(m);
    init_B(j, i) = cast<num_t>(((n + i - j) % 100)) / cast<int>(m);

    // Parallelize over rows (i == original row index).
    // j is innermost, so each worker gets contiguous spans.
    init_C.parallel(i);
    init_B.parallel(i);

    // ----------------------------------
    // Initialize A (symmetric, lower stored)
    // ----------------------------------
    //
    // Original C:
    //   for (i = 0; i < m; i++) {
    //     for (j = 0; j <= i; j++)
    //       A[i][j] = (DATA_TYPE)((i + j) % 100) / m;
