    // Optimized schedule for the SYMM kernel
    // ------------------------------------------------------------------
    //
    // We want to:
    //   - Tile the (i, j) space for better cache locality.
    //   - Parallelize across tiles to use all CPU cores.
    //   - Vectorize across j (the fastest-varying dimension) so that
    //     we load C and B in contiguous vectors.
    //   - Block the reduction in k to improve temporal locality on A/B.
    //
    // Memory layout:
    //   - C(j,i) and B(j,k) are both laid out with j as the innermost
    //     dimension, so vectorizing across j gives contiguous accesses
    //     for both the output and the non-reduction input.
    //
    // Note: We choose sizes TILE_I, TILE_J, TILE_K (see top of file)
    // conservatively. They can be tuned further for a specific machine.

    Target target = get_jit_target_from_environment();
    const int vec_width = natural_vector_size<num_t>(target);

    // Spatial tiling variables
    Var jo("jo"), ji("ji");
    Var io("io"), ii("ii");
    Var tile_index("tile_index");

    // Reduction tiling variables
    RVar ko("ko"), ki("ki");

    // Tile the (j, i) iteration space: j is inner (contiguous), i is outer.
    // This applies to both the pure definition and the update definition.
    symm
        .tile(j, i, jo, io, ji, ii, TILE_J, TILE_I)
        // Fuse the outer tile coordinates into a single parallel loop.
        .fuse(jo, io, tile_index)
        .parallel(tile_index)
        // Vectorize across contiguous j within a tile.
        .vectorize(ji, vec_width);

    // For the reduction update:
    //   - Split k into (ko, ki) so we work on smaller k-blocks that
    //     better fit in cache.
    //   - Reorder so that ki is outside the vectorized j-loop but still
    //     relatively inner, and tile_index stays outermost.
    //   - Vectorize across ji in the reduction as well, so each update
    //     operates on a vector of C and B values.
    symm.update()
        .split(k, ko, ki, TILE_K)
        // Innermost to outermost: ji, ki, ko, ii, tile_index
        // This yields:
        //   for tile_index (parallel)
        //     for ii
        //       for ko
        //         for ki
        //           for ji (vectorized)
        .reorder(ji, ki, ko, ii, tile_index)
        .vectorize(ji, vec_width);

    // Bind buffers to ImageParams
    C_param.set(C);
    A_param.set(A);
    B_param.set(B);

    // JIT-compile the kernel with the chosen target
    symm.compile_jit(target);

    // Time the kernel
    auto start = std::chrono::high_resolution_clock::now();

    // Run kernel: write result back into C
    symm.realize(C);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Print results (mainly to prevent dead-code elimination),
    // following the style of the GEMM example.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int ii = 0; ii < m; ii++) {
