    //   symm(j, i) += alpha * sum_k A_sym(k, i) * B_param(j, k)
    //
    // Precomputing A_sym avoids a data-dependent branch in the hot loop
    // and makes accesses to A contiguous along k, improving locality.
    // ------------------------------------------------------------------

    Func A_sym("A_sym");
    {
        Var kk("kk"), ii("ii");
        A_sym(kk, ii) = select(kk <= ii,
                               A_param(kk, ii),   // lower triangle: A[i][k]
                               A_param(ii, kk));  // upper via symmetry: A[k][i]
    }

    Func symm("symm");

    // Cast scalars to Expr once; they are embedded as compile-time constants
    Expr alpha_e = cast<decltype(alpha)>(alpha);
    Expr beta_e  = cast<decltype(beta)>(beta);

    // Base: beta * C
    symm(j, i) = beta_e * C_param(j, i);

    // Accumulate alpha * A_sym * B
    symm(j, i) += alpha_e * A_sym(k, i) * B_param(j, k);

    // ------------------------------------------------------------------
    // Scheduling for performance
    //
    // We target a modern x64 CPU (up to 32 physical cores). The schedule
    // focuses on:
    //  - Row-major access along j (dimension 0) for C and B, enabling
    //    wide vectorization.
    //  - Tiling in (j, i) to improve cache locality.
    //  - Parallelizing across tiles in the i (row) dimension.
    //  - Precomputing A_sym with a separate schedule.
    //  - Unrolling the inner k-loop slightly to expose ILP.
    // ------------------------------------------------------------------

    Target target = get_host_target();
    const int vec_width = target.natural_vector_size(type_of<num_t>());

    // Tunable tile sizes for cache hierarchy
    const int tile_j = 64;  // tile along j (columns)  - stride-1 dimension
    const int tile_i = 32;  // tile along i (rows)

    // Precompute the symmetric view of A once, in parallel over rows
    {
        Var kk("kk"), ii("ii");
        A_sym
            .compute_root()
            .parallel(ii)            // parallelize over rows of A
            .vectorize(kk, vec_width); // vectorize along contiguous k
    }

    // Tile and parallelize the main kernel
    Var jo("jo"), ji("ji"), io("io"), ii("ii");
    symm
        // Ensure j is the fast-varying (x) dimension.
        .reorder(j, i)
        // Tile (j, i) -> (jo, io outer; ji, ii inner)
        .tile(j, i, jo, io, ji, ii, tile_j, tile_i)
        // Parallelize across tiles in the i (row) dimension.
        .parallel(io)
        // Vectorize across contiguous j within each tile.
        .vectorize(ji, vec_width);

    // Schedule the reduction (update) stage.
    {
        RVar ko("ko"), ki("ki");

        symm.update()
            // Split k to allow a small unrolled inner loop and
            // better instruction-level parallelism.
            .split(k, ko, ki, 4)
            // Order loops from outermost to innermost:
            //   io (tile rows), jo (tile cols),
            //   ii (rows within tile), ko, ki, ji (cols within tile)
            // ji is innermost to maintain vectorization-friendly layout.
            .reorder(ji, ki, ko, ii, jo, io)
            .vectorize(ji, vec_width)
            .unroll(ki);
    }

    // ------------------------------------------------------------------
    // Bind buffers to ImageParams and JIT-compile
    // ------------------------------------------------------------------
    C_param.set(C);
    A_param.set(A);
    B_param.set(B);

    // JIT-compile the kernel for the chosen target
    symm.compile_jit(target);

    // Time the kernel
    auto start = std::chrono::high_resolution_clock::now();

    // Run kernel: write result back into C
    symm.realize(C);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Print results (mainly to prevent dead-code elimination),
    // following the style of the GEMM example.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int ii = 0; ii < m; ii++) {
            for (int jj = 0; jj < n; jj++) {
                // C(ii, jj) in C layout is C(jj, ii) in our Buffer
                std::cerr << C(jj, ii) << '\n';
            }
        }
    }

    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
